export const placementScore = (difficulty: GeneratorDifficulty, features: number[]) => {
    const { w1, b1, w2, b2 } = NETWORKS[difficulty];
    let out = b2;
    for (let h = 0; h < b1.length; h++) {
        let sum = b1[h];
        const weights = w1[h];
        for (let i = 0; i < weights.length; i++) sum += weights[i] * features[i];
        if (sum > 0) out += w2[h] * sum;
    }
    return 1 / (1 + Math.exp(-out));
};
